package at.hausgarten.service;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.widget.*;
import org.json.*;
import java.util.UUID;
import java.util.concurrent.*;

/** One local save and one explicit restore. No account, key setup or cloud controls. */
public final class FullBackupActivity extends Activity {
    private static final int SAVE=203,OPEN=204;
    private static final ExecutorService WORK=Executors.newSingleThreadExecutor();
    private TextView status;private Button save,open,check,activate,newTarget;private EditText legacyCode;private LinearLayout root;
    private boolean busy;private String request="",target="",restoreRequest="",restoreUri="",restoreId="",previewHash="";private boolean legacyMedia;
    @Override public void onCreate(Bundle state){super.onCreate(state);if(RevierApplication.recoveryRequired()){startActivity(new Intent(this,RestoreRecoveryActivity.class));finish();return;}
        PixelBackupService.cancelRetiredJobs(this);setTitle("Sicherung auf dem Pixel");
        if(state!=null){request=state.getString("request","");target=state.getString("target","");restoreRequest=state.getString("restore_request","");restoreUri=state.getString("restore_uri","");}
        root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);int pad=NativeUi.dp(this,16);root.setPadding(pad,pad,pad,pad);root.setFitsSystemWindows(true);
        text("Sicherung auf dem Pixel",22);text("Speichert deinen vollständigen Bestand als ZIP-Datei in einem Ordner auf diesem Pixel. Ohne Internet, Google-Konto oder Passwort. Die Datei ist unverschlüsselt und enthält deine Daten.",17);
        save=button(target.isEmpty()?"Sicherung speichern":"Speichern erneut versuchen",()->{if(target.isEmpty())chooseSave();else save();});
        newTarget=button("Anderen Speicherort wählen",()->{target="";chooseSave();});newTarget.setVisibility(android.view.View.GONE);
        status=text("Noch keine Sicherung gespeichert. Eine Kopie auf demselben Pixel schützt nicht bei Verlust oder Defekt des Geräts.",16);
        open=button("Sicherung wiederherstellen",()->{legacyCode.setText("");legacyCode.setVisibility(android.view.View.GONE);getWindow().clearFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);chooseRestore();});
        legacyCode=new EditText(this);legacyCode.setTextSize(16);legacyCode.setHint("Schlüssel – nur für alte verschlüsselte Sicherungen");legacyCode.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);legacyCode.setSaveEnabled(false);root.addView(legacyCode);
        legacyCode.setVisibility(android.view.View.GONE);
        button("Alte verschlüsselte Sicherung öffnen",()->{legacyCode.setVisibility(android.view.View.VISIBLE);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);chooseRestore();});
        check=button("Gewählte Sicherung prüfen",this::preview);check.setVisibility(restoreUri.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);
        activate=button("Geprüfte Sicherung wiederherstellen",this::confirmRestore);activate.setVisibility(android.view.View.GONE);
        legacyCode.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){restoreRequest="";restoreId="";previewHash="";activate.setVisibility(android.view.View.GONE);}public void afterTextChanged(android.text.Editable e){}});
        button("Zurück",()->{if(busy)status.setText("Die Sicherung läuft noch. Bitte auf das Ergebnis warten.");else finish();});ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);
        WORK.execute(()->{try{JSONObject previous=new BackupRestoreService(this).previousPreservation();if(previous.optBoolean("available")){String activation=previous.getString("activation_request_id");ui(()->button("Bestand vor letzter Wiederherstellung zurückholen",()->{String id=UUID.randomUUID().toString(),code=legacyCode.getText().toString();restoreRequest=id;run(()->showPreview(new BackupRestoreService(this).previewPrevious(id,activation,code)));}));}}catch(Exception unavailable){/* A missing historical proof never blocks a new local save. */}});
    }
    private TextView text(String value,int size){TextView view=NativeUi.text(new TextView(this));view.setTextSize(size);view.setText(value);root.addView(view);return view;}
    private Button button(String label,Runnable action){Button value=NativeUi.style(new Button(this),0);value.setText(label);value.setAllCaps(false);value.setMinHeight(NativeUi.dp(this,52));root.addView(value);value.setOnClickListener(v->{if(!busy)action.run();});return value;}
    private void chooseSave(){target="";request=UUID.randomUUID().toString();Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"Haus-Garten-"+java.time.LocalDateTime.now().format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd-HHmmss"))+".zip");try{startActivityForResult(intent,SAVE);}catch(ActivityNotFoundException unavailable){status.setText("Die Android-Dateiauswahl ist nicht verfügbar.");}}
    private void chooseRestore(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");try{startActivityForResult(intent,OPEN);}catch(ActivityNotFoundException unavailable){status.setText("Die Android-Dateiauswahl ist nicht verfügbar.");}}
    private void run(Task task){if(busy)return;busy=true;save.setEnabled(false);open.setEnabled(false);check.setEnabled(false);activate.setEnabled(false);WORK.execute(()->{try{task.run();}catch(Exception failure){String code=failure.getMessage();if(code==null||!code.matches("(?:BACKUP|RESTORE|RECOVERY|DOCUMENT)_[A-Z0-9_]{1,100}"))code="BACKUP_OPERATION_FAILED";final String safe=code;ui(()->{if(!target.isEmpty())newTarget.setVisibility(android.view.View.VISIBLE);status.setText(safe.equals("BACKUP_PIXEL_FOLDER_REQUIRED")?"Bitte einen Speicherort auf diesem Pixel wählen. Drive und andere Cloud-Anbieter werden nicht verwendet.":"Vorgang nicht abgeschlossen. Der vorhandene Bestand bleibt erhalten. Fehlercode: "+safe);});}finally{ui(()->{busy=false;save.setEnabled(true);open.setEnabled(true);check.setEnabled(true);activate.setEnabled(true);});}});}
    private void ui(Runnable action){runOnUiThread(()->{if(!isDestroyed())action.run();});}
    private void save(){String current=request,destination=target;run(()->{try(PixelLocalStore store=new PixelLocalStore(this)){JSONObject result=new PixelBackupService(this,store).save(current,Uri.parse(destination),message->ui(()->status.setText(message)));if(!result.optBoolean("verified"))throw new java.io.IOException("BACKUP_LOCAL_READBACK_FAILED");ui(()->{status.setText("Sicherung gespeichert und vollständig zurückgelesen. Du findest die ZIP-Datei am gewählten Speicherort auf dem Pixel.");request="";target="";newTarget.setVisibility(android.view.View.GONE);save.setText("Neue Sicherung speichern");});}});}
    private void preview(){if(restoreUri.isEmpty())return;if(restoreRequest.isEmpty())restoreRequest=UUID.randomUUID().toString();String id=restoreRequest,uri=restoreUri,code=legacyCode.getText().toString();run(()->showPreview(new BackupRestoreService(this).preview(id,Uri.parse(uri),code)));}
    private void showPreview(JSONObject result)throws Exception {boolean incomplete=result.optJSONObject("summary")!=null&&result.getJSONObject("summary").optString("media_coverage").equals("LEGACY_NOT_PROVEN");ui(()->{restoreId=result.optString("restore_id");previewHash=result.optString("preview_hash");legacyMedia=incomplete;status.setText("Sicherungsdatei geprüft. Wiederherstellen ersetzt den aktuellen Bestand. Vorher wird eine lokale Rückfallkopie erstellt."+(legacyMedia?" Bei dieser alten Sicherung ist die Fotoabdeckung nicht vollständig belegt.":""));activate.setVisibility(android.view.View.VISIBLE);});}
    private void confirmRestore(){if(restoreId.isEmpty()||previewHash.isEmpty())return;new AlertDialog.Builder(this).setTitle("Bestand wiederherstellen?").setMessage("Der aktuelle Bestand wird durch die geprüfte Sicherung ersetzt. Eine lokale Rückfallkopie bleibt erhalten."+(legacyMedia?" Die unvollständig belegte Fotoabdeckung dieser alten Sicherung wird ausdrücklich akzeptiert.":"")).setNegativeButton("Abbrechen",null).setPositiveButton("Wiederherstellen",(d,w)->{String id=restoreId,hash=previewHash;run(()->{new BackupRestoreService(this).requestActivation("activate_"+restoreRequest,id,hash,true,legacyMedia);ui(()->status.setText("Wiederherstellung vorgemerkt. App vollständig schließen und erneut öffnen. Der Austausch erfolgt beim Neustart."));});}).show();}
    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{PixelBackupService.requirePixel(uri);if(!"content".equals(uri.getScheme()))throw new java.io.IOException("DOCUMENT_URI_REQUIRED");int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{getContentResolver().takePersistableUriPermission(uri,flags);}catch(SecurityException temporary){/* This explicit operation may use its temporary grant. */}if(code==SAVE){target=uri.toString();save.setText("Speichern erneut versuchen");save();}else if(code==OPEN){restoreUri=uri.toString();restoreRequest="";restoreId="";previewHash="";activate.setVisibility(android.view.View.GONE);check.setVisibility(android.view.View.VISIBLE);status.setText("Sicherungsdatei gewählt. Mit „Gewählte Sicherung prüfen“ fortfahren.");}}catch(Exception invalid){status.setText("Bitte eine Datei auf diesem Pixel auswählen. Es wurde keine Sicherung geschrieben.");request="";target="";}}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("request",request);state.putString("target",target);state.putString("restore_request",restoreRequest);state.putString("restore_uri",restoreUri);/* Never serialize an old recovery code. */}
    interface Task {void run()throws Exception;}
}
